mapper.update:
UPDATE t_post
title = #{title}, slug = #{slug}, summary = #{summary}, content = #{content}, cover_image = #{coverImage}, status = #{status}, is_top = #{isTop}, allow_comment = #{allowComment}, published_at = #{publishedAt}, updated_at = NOW()
WHERE id = #{id}

mapper.select:
SELECT DISTINCT p.id, p.user_id, p.title, p.slug, p.summary, p.cover_image, p.status, p.is_top, p.allow_comment, p.view_count, p.published_at, p.created_at, p.updated_at FROM t_post p

    INNER JOIN t_post_category pc ON p.id = pc.post_id AND pc.category_id = #{categoryId}


    INNER JOIN t_post_tag pt ON p.id = pt.post_id AND pt.tag_id = #{tagId}

WHERE p.status = 1

    AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.summary LIKE CONCAT('%', #{keyword}, '%'))

ORDER BY p.is_top DESC, p.published_at DESC

SELECT DISTINCT p.id, p.user_id, p.title, p.slug, p.summary, p.cover_image, p.status, p.is_top, p.allow_comment, p.view_count, p.published_at, p.created_at, p.updated_at FROM t_post p

    INNER JOIN t_post_category pc ON p.id = pc.post_id AND pc.category_id = #{categoryId}

WHERE 1=1

    AND p.status = #{status}


    AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.summary LIKE CONCAT('%', #{keyword}, '%'))

ORDER BY p.created_at DESC

SELECT p.id, p.user_id, p.title, p.slug, p.summary, p.cover_image, p.status, p.is_top, p.allow_comment, p.view_count, p.published_at, p.created_at, p.updated_at FROM t_post p
WHERE p.user_id = #{userId}

    AND p.status = #{status}


    AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.summary LIKE CONCAT('%', #{keyword}, '%'))

ORDER BY p.created_at DESC
